<?php
const MOD = 998244353;
const MAXN = 5100; // s up to 5000

function modpow($a, $e = MOD - 2) {
    $res = 1;
    while ($e > 0) {
        if ($e & 1) $res = ($res * $a) % MOD;
        $a = ($a * $a) % MOD;
        $e >>= 1;
    }
    return $res;
}

$fact = array_fill(0, MAXN, 1);
for ($i = 1; $i < MAXN; $i++) {
    $fact[$i] = ($fact[$i - 1] * $i) % MOD;
}
$inv_fact = array_fill(0, MAXN, 1);
$inv_fact[MAXN - 1] = modpow($fact[MAXN - 1]);
for ($i = MAXN - 2; $i >= 0; $i--) {
    $inv_fact[$i] = ($inv_fact[$i + 1] * ($i + 1)) % MOD;
}

function nCr($n, $k) {
    global $fact, $inv_fact;
    if ($k < 0 || $k > $n) return 0;
    return (($fact[$n] * $inv_fact[$k]) % MOD * $inv_fact[$n - $k]) % MOD;
}

function starsAndBars($n, $k) {
    if ($n < 0) return 0;
    if ($k == 0) return $n == 0 ? 1 : 0;
    return nCr($n + $k - 1, $k - 1);
}

$input = trim(fgets(STDIN));
if ($input === false) exit;
list($p, $s, $r) = array_map('intval', explode(' ', $input));

$total_ways = starsAndBars($s - $r, $p);

$win_ways = 0;

for ($x = $r; $x <= $s; $x++) {
    $rem_sum = $s - $x;
    $others = $p - 1;
    if ($rem_sum < 0) continue;

    $ways_all_le_x = 0;
    $max_k = min($others, (int)($rem_sum / $x)); // floor division
    for ($k = 0; $k <= $max_k; $k++) {
        $sign = ($k % 2 == 0) ? 1 : -1;
        $choose_players = nCr($others, $k);
        $remaining_sum = $rem_sum - $k * $x;
        $ways_dist = starsAndBars($remaining_sum, $others);
        $term = ($choose_players * $ways_dist) % MOD;
        $ways_all_le_x = ($ways_all_le_x + $sign * $term) % MOD;
    }
    $ways_all_le_x = ($ways_all_le_x + MOD) % MOD;

    $ways_all_le_xm1 = 0;
    if ($x > 0) {
        $max_k2 = min($others, (int)($rem_sum / ($x - 1)));
        for ($k = 0; $k <= $max_k2; $k++) {
            $sign = ($k % 2 == 0) ? 1 : -1;
            $choose_players = nCr($others, $k);
            $remaining_sum = $rem_sum - $k * ($x - 1);
            $ways_dist = starsAndBars($remaining_sum, $others);
            $term = ($choose_players * $ways_dist) % MOD;
            $ways_all_le_xm1 = ($ways_all_le_xm1 + $sign * $term) % MOD;
        }
        $ways_all_le_xm1 = ($ways_all_le_xm1 + MOD) % MOD;
    } else {
        $ways_all_le_xm1 = 0;
    }

    $contribution1 = $ways_all_le_xm1;

    $contribution2 = 0;
    for ($k = 1; $k <= $others; $k++) {
        if ($k * $x > $rem_sum) break;
        $rem_after_tie = $rem_sum - $k * $x;
        $rem_players = $others - $k;

        $ways_rest = 0;
        if ($x > 0) {
            $max_j = min($rem_players, (int)($rem_after_tie / ($x - 1)));
            for ($j = 0; $j <= $max_j; $j++) {
                $sign = ($j % 2 == 0) ? 1 : -1;
                $choose_players = nCr($rem_players, $j);
                $remaining_sum = $rem_after_tie - $j * ($x - 1);
                $ways_dist = starsAndBars($remaining_sum, $rem_players);
                $term = ($choose_players * $ways_dist) % MOD;
                $ways_rest = ($ways_rest + $sign * $term) % MOD;
            }
            $ways_rest = ($ways_rest + MOD) % MOD;
        } else {
            $ways_rest = ($rem_after_tie == 0 && $rem_players == 0) ? 1 : 0;
        }

        $ways_choose_tied = nCr($others, $k);
        $prob_win_tie = modpow($k + 1);

        $add = $ways_choose_tied * $ways_rest % MOD * $prob_win_tie % MOD;
        $contribution2 = ($contribution2 + $add) % MOD;
    }

    $win_ways = ($win_ways + $contribution1 + $contribution2) % MOD;
}

$ans = $win_ways * modpow($total_ways) % MOD;
echo $ans . "\n";
